draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // ground
  ctx.beginPath();
  ctx.moveTo(0, H - 50);
  ctx.lineTo(W, H - 50);
  ctx.stroke();

  // seed
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2, H - 75, 10, 0, 2 * Math.PI);
  ctx.fill();

  // sprout
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 75);
  ctx.lineTo(W / 2, H - 75 - 50 * Math.sin(t));
  ctx.stroke();

  // leaves
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 75 - 50 * Math.sin(t));
  ctx.lineTo(W / 2 - 20 * Math.cos(t), H - 75 - 70 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 75 - 50 * Math.sin(t));
  ctx.lineTo(W / 2 + 20 * Math.cos(t), H - 75 - 70 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
